// Ustawianie innerHTML danymi od uzytkownika jest ryzykowne, poniewaz
// przegladarka INTERPRETUJE ten tekst jako prawdziwy HTML - jesli
// uzytkownik wpisze np. <script>zlosliwyKod()</script>, ten kod
// zostanie FAKTYCZNIE WYKONANY w przegladarce kazdej osoby, ktora
// zobaczy te tresc (atak XSS - Cross-Site Scripting).

const komentarzUzytkownika = "Super produkt! <script>zly()</script>";
document.getElementById("komentarze").textContent = komentarzUzytkownika;
// textContent wstawia caly string DOSLOWNIE jako tekst - nawet jesli
// zawiera znaczniki <script>, zostana one pokazane jako ZWYKLE ZNAKI
// na stronie, a NIE wykonane jako kod. To calkowicie eliminuje ryzyko
// ataku XSS przy wyswietlaniu danych pochodzacych od uzytkownika.
